#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,amount;scanf("%d %d",&n,&amount);
vector<int>c(n);for(int i=0;i<n;++i)scanf("%d",&c[i]);
const int INF=1e9;
vector<int>dp(amount+1,INF);dp[0]=0;
for(int i=1;i<=amount;++i)
for(int co:c)if(co<=i&&dp[i-co]+1<dp[i])dp[i]=dp[i-co]+1;
printf("%d\n",dp[amount]==INF?-1:dp[amount]);return 0;}

